    load(id) {
      if (!id.startsWith(rendererIndexPath) || !id.includes("playgroundEntry=shell")) return;
      return stripPlaygroundRendererPuzzleHosts(readFileSync(rendererIndexPath, "utf8"), { includeVitest: false });
